// Chapter names in the events data don't always exactly match the PDF's naming
// (e.g. "YPO Dubai" in events vs "YPO Dubai Integrated" in this list). This
// normalizes both sides — strips a trailing "Integrated", trims, lowercases —
// so they match reliably. Edit here if a chapter's naming diverges further.
function normalizeChapterName(name: string): string {
  return name
    .trim()
    .replace(/\s+integrated$/i, "")
    .toLowerCase();
}

export function getLearningOfficer(chapterName: string): LearningOfficer | null {
  const target = normalizeChapterName(chapterName);
  return LEARNING_OFFICERS.find((lo) => normalizeChapterName(lo.chapterName) === target) ?? null;
}

